const found=[];o:for(let o=0;o<5;o++)for(let t=0;t<5;t++){if(o*t>6)break o;found.push(o+"*"+t+"="+o*t)}print("break outer trail:",found.join(" | "));const skipped=[];o:for(let o=0;o<4;o++)for(let t=0;t<4;t++){if(t===o)continue o;skipped.push(o+","+t)}print("continue outer trail:",skipped.join(" | "));